func decrypt(key, ciphertext []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	iv := ciphertext[:aes.BlockSize]
	ct := make([]byte, len(ciphertext)-aes.BlockSize)
	copy(ct, ciphertext[aes.BlockSize:])
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(ct, ct)
	return ct, nil
}

func tryKey(keyStr string) {
	if len(keyStr) != 32 {
		fmt.Printf("  [skip key len %d]\n", len(keyStr))
		return
	}
	data, err := hex.DecodeString(cipherHex)
	if err != nil {
		fmt.Println("hex err", err)
		return
	}
	pt, err := decrypt([]byte(keyStr), data)
	if err != nil {
		fmt.Println("  aes err:", err)
		return
	}
	printable := true
	for _, b := range pt {
		if b < 32 || b > 126 {
			printable = false
			break
		}
	}
	tag := "NOT-printable"
	if printable {
		tag = "*** PRINTABLE ***"
	}
	fmt.Printf("  key=%s pt=%q %s\n", keyStr, string(pt), tag)
}

func win() {
	won = true
	h := md5.Sum([]byte(doneMoves))
