func checkMove(x, y, dir int) bool {
	if movesNeeded > 0 {
		movesNeeded--
		return false
	}
	switch dir {
	case 0:
		if m[x-1][y] == "#" || m[x-1][y] == "M" || m[x-1][y] == "W" {
			return false
		}
	case 1:
		if m[x][y+1] == "#" || m[x][y+1] == "M" || m[x][y+1] == "W" {
			return false
		}
	case 2:
		if m[x+1][y] == "#" || m[x+1][y] == "M" || m[x+1][y] == "W" {
			return false
		}
	case 3:
		if m[x][y-1] == "#" || m[x][y-1] == "M" || m[x][y-1] == "W" {
			return false
		}
	}
	return true
}

func move(x, y, dir int) (int, int) {
	if checkMove(x, y, dir) {
		var tx, ty int
		switch dir {
		case 0:
			tx, ty = x-1, y
		case 1:
			tx, ty = x, y+1
		case 2:
			tx, ty = x+1, y
		case 3:
			tx, ty = x, y-1
		}
		if m[tx][ty] == "X" {
			movesNeeded = 1
		}
		if m[tx][ty] == "F" {
			win()
			return tx, ty
		}
		if canPickupPickaxe {
			canPickupPickaxe = false
		}
		if m[tx][ty] == "P" {
			canPickupPickaxe = true
		}
		m[x][y] = " "
		m[tx][ty] = "S"
		return tx, ty
	}
	return x, y
}

func simulate(tokens []string, verbose bool) {
	m = baseMap
