func tokenize(s string) []string {
	// split concatenated words like downdowndownright...
	toks := []string{}
	keys := []string{"right", "brace", "fight", "picket", "mine", "pickup", "left", "down", "quit", "up"}
	for len(s) > 0 {
		matched := false
		// try longest match
		best := ""
		for _, k := range keys {
			if strings.HasPrefix(s, k) && len(k) > len(best) {
				best = k
			}
		}
		if best == "" {
			panic("cannot tokenize at: " + s)
		}
		toks = append(toks, best)
		s = s[len(best):]
		_ = matched
	}
	return toks
}

