	hint := "downdowndownrightdowndownbracefightfightfightrightrightrightupupleftpickuprightdowndownrightdownrightmineright"
	toks := tokenize(hint)
	fmt.Printf("tokens (%d): %v\n\n", len(toks), toks)

	fmt.Println("=== simulate hint as-is ===")
	simulate(toks, true)
	fmt.Println()
	for _, extra := range []int{1, 2, 3, 4} {
		fmt.Printf("=== simulate hint + %d extra rights ===\n", extra)
		t := append([]string{}, toks...)
		for i := 0; i < extra; i++ {
			t = append(t, "right")
		}
		simulate(t, false)
		fmt.Println()
	}

	fmt.Println("=== direct key tests on hint-derived strings ===")
	h1 := strings.Join(toks, "")
	fmt.Printf("hint string: %s\n", h1)
	sum := md5.Sum([]byte(h1))
	fmt.Printf("md5(hint)=%s\n", hex.EncodeToString(sum[:]))
	tryKey(hex.EncodeToString(sum[:]))
