	if strings.HasSuffix(h1, "right") {
		h2 := strings.TrimSuffix(h1, "right")
		s2 := md5.Sum([]byte(h2))
		fmt.Printf("hint-minus-last-right: %s\n", h2)
		fmt.Printf("md5=%s\n", hex.EncodeToString(s2[:]))
		tryKey(hex.EncodeToString(s2[:]))
	}
	os.Exit(0)
}
"}

