{"content": "package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/md5"
	"encoding/hex"
	"fmt"
	"os"
	"regexp"
	"strconv"
	"strings"
)

const ctHex = "018a267bc43a4a1759eef7fec74179fb9c5733658e7ed86658286de4158aa6b80cedfc70e93981f7dea13bdbe740a141"

var initialMap = [10][10]byte{
	{'#', '#', '#', '#', '#', '#', '#', '#', '#', '#'},
	{'#', 'S', 'X', '#', ' ', ' ', ' ', ' ', '#', '#'},
	{'#', ' ', 'X', '#', ' ', ' ', ' ', ' ', '#', '#'},
	{'#', ' ', 'X', '#', 'X', 'X', 'X', ' ', '#', '#'},
	{'#', ' ', ' ', '#', 'P', ' ', 'X', 'X', '#', '#'},
	{'#', '#', ' ', 'W', 'W', ' ', 'X', 'X', '#', '#'},
	{'#', 'X', ' ', 'M', ' ', ' ', ' ', 'X', 'W', '#'},
	{'#', 'W', 'W', 'W', 'W', 'X', ' ', ' ', 'W', 'F'},
	{'#', 'X', 'X', 'X', 'X', 'X', 'X', 'X', 'W', '#'},
	{'#', '#', '#', '#', '#', '#', '#', '#', '#', '#'},
}

type State struct {
	M           [10][10]byte
	X, Y        int
	MovesNeeded int
	HasPickaxe  bool
	CanPickup   bool
	IsBraced    bool
	MonsterHp   int
	Done        string
}

func newState() *State {
	s := &State{X: 1, Y: 1, MonsterHp: 3}
	s.M = initialMap
	return s
}

func clone(s *State) *State { n := *s; return &n }

func checkMove(s *State, dir int) bool {
	if s.MovesNeeded > 0 {
		s.MovesNeeded--
		return false
	}
	switch dir {
	case 0:
		c := s.M[s.X-1][s.Y]
		if c == '#' || c == 'M' || c == 'W' {
			return false
		}
	case 1:
		c := s.M[s.X][s.Y+1]
		if c == '#' || c == 'M' || c == 'W' {
			return false
		}
	case 2:
		c := s.M[s.X+1][s.Y]
		if c == '#' || c == 'M' || c == 'W' {
			return false
		}
	case 3:
		c := s.M[s.X][s.Y-1]
		if c == '#' || c == 'M' || c == 'W' {
			return false
		}
	}
	return true
}

// move mirrors the Go source: win() fires before the map is mutated and
// before done_moves is appended by main().
func move(s *State, dir int) (*State, bool) {
	if !checkMove(s, dir) {
		return s, false
	}
	var nx, ny int
	switch dir {
	case 0:
		nx, ny = s.X-1, s.Y
	case 1:
		nx, ny = s.X, s.Y+1
	case 2:
		nx, ny = s.X+1, s.Y
	case 3:
		nx, ny = s.X, s.Y-1
	}
	cell := s.M[nx][ny]
	if cell == 'X' {
		s.MovesNeeded = 1
	}
	if cell == 'F' {
		return s, true
	}
	if s.CanPickup {
		s.CanPickup = false
	}
	if cell == 'P' {
		s.CanPickup = true
	}
	s.M[s.X][s.Y] = ' '
	s.M[nx][ny] = 'S'
	s.X, s.Y = nx, ny
	return s, false
}

func clearAdjW(s *State) {
	if s.M[s.X-1][s.Y] == 'W' {
		s.M[s.X-1][s.Y] = ' '
	}
	if s.M[s.X+1][s.Y] == 'W' {
		s.M[s.X+1][s.Y] = ' '
	}
	if s.M[s.X][s.Y-1] == 'W' {
		s.M[s.X][s.Y-1] = ' '
	}
	if s.M[s.X][s.Y+1] == 'W' {
		s.M[s.X][s.Y+1] = ' '
	}
}

func clearAdjM(s *State) {
	if s.M[s.X-1][s.Y] == 'M' {
		s.M[s.X-1][s.Y] = ' '
	}
	if s.M[s.X+1][s.Y] == 'M' {
		s.M[s.X+1][s.Y] = ' '
	}
	if s.M[s.X][s.Y-1] == 'M' {
		s.M[s.X][s.Y-1] = ' '
	}
	if s.M[s.X][s.Y+1] == 'M' {
		s.M[s.X][s.Y+1] = ' '
	}
}

func adjM(s *State) bool {
	return s.M[s.X-1][s.Y] == 'M' || s.M[s.X+1][s.Y] == 'M' ||
		s.M[s.X][s.Y-1] == 'M' || s.M[s.X][s.Y+1] == 'M'
}

// apply performs one command line ("go up" etc.) faithfully; it returns
// won=true if win() would have been called, with Done equal to done_moves at
// that instant (i.e. before the triggering command is appended for moves).
func apply(s *State, cmd string) (*State, bool) {
	n := clone(s)
	switch cmd {
	case "up", "right", "down", "left":
		dir := map[string]int{"up": 0, "right": 1, "down": 2, "left": 3}[cmd]
		_, won := move(n, dir)
		if won {
			return n, true
		}
		n.Done += cmd
		return n, false
	case "mine":
		n.Done += "mine"
		if n.HasPickaxe {
			clearAdjW(n)
		}
		return n, false
	case "brace":
		n.Done += "brace"
		if adjM(n) {
			n.IsBraced = true
		}
		return n, false
	case "fight":
		n.Done += "fight"
		if adjM(n) {
			n.MonsterHp--
			if n.MonsterHp == 0 {
				clearAdjM(n)
			}
			if !n.IsBraced {
				_, won := move(n, 3)
				if won {
					return n, true
				}
			}
		}
		return n, false
	case "pickup":
		n.Done += "pickup"
		if n.CanPickup {
			n.HasPickaxe = true
			n.CanPickup = false
		}
		return n, false
	}
	return n, false
}

var cmds = []string{"up", "right", "down", "left", "mine", "brace", "fight", "pickup"}

func sig(s *State) string {
	b := make([]byte, 0, 112)
	for i := 0; i < 10; i++ {
		b = append(b, s.M[i][:]...)
	}
	f := byte(0)
	if s.HasPickaxe {
		f |= 1
	}
	if s.CanPickup {
		f |= 2
	}
	if s.IsBraced {
		f |= 4
	}
	b = append(b, byte(s.X), byte(s.Y), byte(s.MovesNeeded), f, byte(s.MonsterHp+10))
	return string(b)
}

var flagRe = regexp.MustCompile(`^[A-Za-z0-9_]{3,6}\{[ -~]{20,40}\}$`)

func decryptReport(done string, tag string) {
	sum := md5.Sum([]byte(done))
	key := hex.EncodeToString(sum[:])
	data, err := hex.DecodeString(ctHex)
	if err != nil {
		fmt.Println("hex decode error:", err)
		return
	}
	block, err := aes.NewCipher([]byte(key))
	if err != nil {
		fmt.Println("aes error:", err)
		return
	}
	out := make([]byte, len(data)-16)
	cipher.NewCBCDecrypter(block, data[:16]).CryptBlocks(out, data[16:])
	printable := true
	for _, c := range out {
		if c < 32 || c > 126 {
			printable = false
		}
	}
	fmt.Printf("%s done=%q (len=%d)\n  md5=%s printable=%v flagMatch=%v plaintext=%q\n",
		tag, done, len(done), key, printable, flagRe.Match(out), string(out))
}

func tokenize(s string) []string {
	var out []string
	words := []string{"pickup", "brace", "fight", "right", "down", "left", "mine", "up"}
	for i := 0; i < len(s); {
		matched := false
		for _, w := range words {
			if strings.HasPrefix(s[i:], w) {
				out = append(out, w)
				i += len(w)
				matched = true
				break
			}
		}
		if !matched {
			fmt.Printf("tokenize failed at %q\n", s[i:])
			return out
		}
	}
	return out
}

func runSeq(tokens []string, label string) {
	s := newState()
	for i, t := range tokens {
		var won bool
		s, won = apply(s, t)
		if won {
			fmt.Printf("%s: win at command #%d (%q)\n", label, i+1, t)
			decryptReport(s.Done, "  WIN")
			return
		}
	}
	fmt.Printf("%s: no win after %d commands (pos=%d,%d)\n", label, len(tokens), s.X, s.Y)
}

func main() {
	mode := "hint"
	if len(os.Args) > 1 {
		mode = os.Args[1]
	}
	if mode == "hint" {
		const hint = "downdowndownrightdowndownbracefightfightfightrightrightrightupupleftpickuprightdowndownrightdownrightmineright"
		toks := tokenize(hint)
		fmt.Printf("hint token count=%d\n", len(toks))
		runSeq(toks, "hint-only")
		runSeq(append(append([]string{}, toks...), "right"), "hint+right")
		runSeq(append(append([]string{}, toks...), "up"), "hint+up")
		return
	}
	maxDepth := 30
	maxNodes := 4000000
	if len(os.Args) > 2 {
		maxDepth, _ = strconv.Atoi(os.Args[2])
	}
	if len(os.Args) > 3 {
		maxNodes, _ = strconv.Atoi(os.Args[3])
	}
	start := newState()
	queue := []*State{start}
	visited := map[string]bool{sig(start): true}
	head := 0
	type winRec struct {
		depth int
		state *State
	}
	var wins []winRec
	seenWin := map[string]bool{}
	depthOf := map[*State]int{start: 0}
	for head < len(queue) && len(visited) < maxNodes {
		cur := queue[head]
		head++
		d := depthOf[cur]
		if d >= maxDepth {
			continue
		}
		for _, c := range cmds {
			ns, won := apply(cur, c)
			if won {
				if !seenWin[ns.Done] {
					seenWin[ns.Done] = true
					wins = append(wins, winRec{d + 1, ns})
				}
				continue
			}
			k := sig(ns)
			if !visited[k] {
				visited[k] = true
				depthOf[ns] = d + 1
				queue = append(queue, ns)
			}
		}
		if len(visited)%500000 == 0 {
			fmt.Printf("progress: visited=%d head=%d depth=%d wins=%d\n", len(visited), head, d, len(wins))
		}
	}
	fmt.Printf("BFS finished/stopped: visited=%d head=%d queue=%d wins=%d reachedMaxDepth=%v hitCap=%v\n",
		len(visited), head, len(queue), len(wins), head >= len(queue), len(visited) >= maxNodes)
	for _, w := range wins {
		fmt.Printf("win depth=%d\n", w.depth)
		decryptReport(w.state.Done, "  WIN")
	}
}
