{"content": "package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/md5"
	"encoding/hex"
	"flag"
	"fmt"
	"regexp"
	"sort"
	"strings"
)

const ctHex = "018a267bc43a4a1759eef7fec74179fb9c5733658e7ed86658286de4158aa6b80cedfc70e93981f7dea13bdbe740a141"

var base = [10][10]byte{
	{'#', '#', '#', '#', '#', '#', '#', '#', '#', '#'},
	{'#', 'S', 'X', '#', ' ', ' ', ' ', ' ', '#', '#'},
	{'#', ' ', 'X', '#', ' ', ' ', ' ', ' ', '#', '#'},
	{'#', ' ', 'X', '#', 'X', 'X', 'X', ' ', '#', '#'},
	{'#', ' ', ' ', '#', 'P', ' ', 'X', 'X', '#', '#'},
	{'#', '#', ' ', 'W', 'W', ' ', 'X', 'X', '#', '#'},
	{'#', 'X', ' ', 'M', ' ', ' ', ' ', 'X', 'W', '#'},
	{'#', 'W', 'W', 'W', 'W', 'X', ' ', ' ', 'W', 'F'},
	{'#', 'X', 'X', 'X', 'X', 'X', 'X', 'X', 'W', '#'},
	{'#', '#', '#', '#', '#', '#', '#', '#', '#', '#'},
}

type state struct {
	m       [10][10]byte
	x, y    int
	moves   int // movesNeeded
	pickup  bool
	canPick bool
	braced  bool
	mhp     int
	done    string
}

func newState() *state {
	s := &state{x: 1, y: 1, mhp: 3, braced: false}
	s.m = base
	return s
}

func (s *state) sig() string {
	var b strings.Builder
	for i := 0; i < 10; i++ {
		for j := 0; j < 10; j++ {
			b.WriteByte(s.m[i][j])
		}
	}
	fmt.Fprintf(&b, "|%d,%d|%d|%v|%v|%v|%d", s.x, s.y, s.moves, s.pickup, s.canPick, s.braced, s.mhp)
	return b.String()
}

func idx(x, y int) bool { return x >= 0 && x < 10 && y >= 0 && y < 10 }

// checkMove mirrors rpgo.go exactly (returns ok). crashed=true means the real
// binary would panic with index out of range.
func (s *state) checkMove(dir int) (ok bool, crashed bool) {
	if s.moves > 0 {
		s.moves--
		return false, false
	}
	nx, ny := s.x, s.y
	switch dir {
	case 0:
		nx--
	case 1:
		ny++
	case 2:
		nx++
	case 3:
		ny--
	}
	if !idx(nx, ny) {
		return false, true
	}
	c := s.m[nx][ny]
	if c == '#' || c == 'M' || c == 'W' {
		return false, false
	}
	return true, false
}

func (s *state) clone() *state {
	n := *s
	return &n
}

// apply runs one command ("up","right","down","left","mine","brace","fight","pickup").
// returns (won, crashed). On won, s.done is the done_moves value at win() time
// (i.e. BEFORE the winning command is appended).
func (s *state) apply(cmd string) (won, crashed bool) {
	switch cmd {
	case "up", "right", "down", "left":
		dir := map[string]int{"up": 0, "right": 1, "down": 2, "left": 3}[cmd]
		ok, cr := s.checkMove(dir)
		if cr {
			return false, true
		}
		if !ok {
			// main still appends the command
			s.done += cmd
			return false, false
		}
		dx := []int{-1, 0, 1, 0}
		dy := []int{0, 1, 0, -1}
		nx, ny := s.x+dx[dir], s.y+dy[dir]
		t := s.m[nx][ny]
		if t == 'X' {
			s.moves = 1
		}
		if t == 'F' {
			// win() before done_moves append and before map mutation
			return true, false
		}
		if s.canPick {
			s.canPick = false
		}
		if t == 'P' {
			s.canPick = true
		}
		s.m[s.x][s.y] = ' '
		s.m[nx][ny] = 'S'
		s.x, s.y = nx, ny
		s.done += cmd
		return false, false
	case "mine":
		s.done += "mine"
		if s.pickup {
			for _, d := range [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}} {
				ax, ay := s.x+d[0], s.y+d[1]
				if idx(ax, ay) && s.m[ax][ay] == 'W' {
					s.m[ax][ay] = ' '
				}
			}
		}
		return false, false
	case "brace":
		s.done += "brace"
		if s.m[s.x-1][s.y] == 'M' || s.m[s.x+1][s.y] == 'M' || s.m[s.x][s.y-1] == 'M' || s.m[s.x][s.y+1] == 'M' {
			s.braced = true
		}
		return false, false
	case "fight":
		s.done += "fight"
		if s.m[s.x-1][s.y] == 'M' || s.m[s.x+1][s.y] == 'M' || s.m[s.x][s.y-1] == 'M' || s.m[s.x][s.y+1] == 'M' {
			s.mhp--
			if s.mhp == 0 {
				for _, d := range [][2]int{{-1, 0}, {1, 0}, {0, -1}, {0, 1}} {
					ax, ay := s.x+d[0], s.y+d[1]
					if idx(ax, ay) && s.m[ax][ay] == 'M' {
						s.m[ax][ay] = ' '
					}
				}
			}
			if !s.braced {
				// knockback: move(x,y,3); illegal/muddy move just costs a turn
				if ok, cr := s.checkMove(3); cr {
					return false, true
				} else if ok {
					s.m[s.x][s.y] = ' '
					s.m[s.x][s.y-1] = 'S'
					s.y--
				}
			}
		}
		return false, false
	case "pickup":
		s.done += "pickup"
		if s.canPick {
			s.pickup = true
			s.canPick = false
		}
		return false, false
	}
	return false, false
}

var validFlag = regexp.MustCompile(`^[A-Za-z0-9_]{3,6}\{[ -~]{20,40}\}$`)

// tryKey computes md5(done), AES-256-CBC decrypts ctHex (IV-prefixed) and
// reports printable plaintext.
func tryKey(done string) (key string, pt []byte, printable bool, ok bool) {
	h := md5.Sum([]byte(done))
	key = hex.EncodeToString(h[:])
	raw, err := hex.DecodeString(ctHex)
	if err != nil || len(raw) < 32 || (len(raw)-16)%16 != 0 {
		return key, nil, false, false
	}
	block, err := aes.NewCipher([]byte(key))
	if err != nil {
		return key, nil, false, false
	}
	iv, body := raw[:16], make([]byte, len(raw)-16)
	copy(body, raw[16:])
	cipher.NewCBCDecrypter(block, iv).CryptBlocks(body, body)
	printable = true
	for _, b := range body {
		if b < 32 || b > 126 {
			printable = false
			break
		}
	}
	return key, body, printable, true
}

func report(done string, verbose bool) bool {
	key, pt, printable, ok := tryKey(done)
	if verbose {
		fmt.Printf("done_moves(%d)=%q\nkey=%s\nplaintext=%q printable=%v\n", len(done), done, key, string(pt), printable)
	}
	if ok && printable && validFlag.MatchString(string(pt)) {
		fmt.Printf("*** FLAG FOUND ***\ndone_moves=%q\nmd5_key=%s\nplaintext=%s\n", done, key, string(pt))
		return true
	}
	return false
}

func main() {
	depth := flag.Int("depth", 34, "BFS depth limit")
	cand := flag.String("cand", "", "test this done_moves string")
	maxWin := flag.Int("maxwin", 5000, "max distinct winning done_moves to test")
	flag.Parse()

	if *cand != "" {
		if !report(*cand, true) {
			fmt.Println("candidate did not decrypt to a flag")
		}
		return
	}

	// BFS over commands; states deduped by full game signature (done_moves
	// excluded so paths stay shortest), every win event tested for the flag.
	type node struct {
		s    *state
		path string
	}
	root := newState()
	seen := map[string]bool{root.sig(): true}
	queue := []node{{root, ""}}
	wins := map[string]bool{}
	names := []string{"up", "right", "down", "left", "mine", "brace", "fight", "pickup"}
	flagFound := false
	for d := 0; d <= *depth && len(queue) > 0; d++ {
		var next []node
		for _, n := range queue {
			for _, cmd := range names {
				ns := n.s.clone()
				won, crashed := ns.apply(cmd)
				if crashed {
					continue
				}
				np := n.path
				if np == "" {
					np = cmd
				} else {
					np = np + "," + cmd
				}
				if won {
					if !wins[ns.done] {
						wins[ns.done] = true
						if report(ns.done, false) {
							flagFound = true
						}
						if len(wins) >= *maxWin {
							d = *depth + 1
							break
						}
					}
					continue
				}
				sg := ns.sig()
				if !seen[sg] {
					seen[sg] = true
					next = append(next, node{ns, np})
				}
			}
			if d > *depth {
				break
			}
		}
		fmt.Printf("depth %d: frontier=%d states_seen=%d wins=%d flag=%v\n", d, len(next), len(seen), len(wins), flagFound)
		queue = next
	}
	keys := make([]string, 0, len(wins))
	for k := range wins {
		keys = append(keys, k)
	}
	sort.Slice(keys, func(i, j int) bool { return len(keys[i]) < len(keys[j]) })
	fmt.Printf("total distinct winning done_moves: %d\n", len(keys))
	for i, k := range keys {
